// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Product} from "../src/Product.sol";

interface IControllerSetter {
    function updateMinCollateral(uint256) external;
    function minCollateral() external view returns (uint256);
}

contract FakeController is IControllerSetter {
    uint256 public minColl;
    function updateMinCollateral(uint256 v) external { minColl = v; }
    function minCollateral() external view returns (uint256) { return minColl; }
    function isProduct(Product) external pure returns (bool) { return true; }
    function coordinatorFor(Product) external pure returns (uint256) { return 0; }
    function owner(uint256) external view returns (address) { return address(this); }
    function collateral() external view returns (address) { return address(0); }
    function incentivizer() external view returns (address) { return address(0); }
}

contract InvMutTest is Test {
    Product c;
    FakeController ctrl;

    function setUp() public {
        c = new Product();
        ctrl = new FakeController();
    }

    function testFuzz_property(uint256 storedMaintenanceRaw, uint256 controllerMinCollateralRaw) public {
        uint256 stored = bound(storedMaintenanceRaw, 0, type(uint128).max);
        uint256 ctrlMin = bound(controllerMinCollateralRaw, 0, type(uint128).max);

        ctrl.updateMinCollateral(ctrlMin);

        bool okRef;
        bytes memory ret;
        (bool success, bytes memory data) = address(c).call(abi.encodeWithSignature("maintenance()"));
        if (success) {
            okRef = true;
            ret = data;
        } else {
            okRef = false;
        }

        uint256 decoded = 0;
        if (okRef && ret.length >= 32) decoded = abi.decode(ret, (uint256));
        assertTrue(okRef && decoded == 0);
    }
}
